export interface Message {
  id: string;
  sender: 'user' | 'mahiru';
  text: string;
  timestamp: Date;
}

export enum ConnectionStatus {
  DISCONNECTED = 'DISCONNECTED',
  CONNECTING = 'CONNECTING',
  CONNECTED = 'CONNECTED',
  ERROR = 'ERROR'
}

export function encode(bytes: Uint8Array): string {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

export function decode(base64: string): Uint8Array {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

export function createBlob(data: Float32Array): { data: string; mimeType: string } {
  const l = data.length;
  const int16 = new Int16Array(l);
  for (let i = 0; i < l; i++) {
    int16[i] = data[i] * 32768;
  }
  return {
    data: encode(new Uint8Array(int16.buffer)),
    mimeType: 'audio/pcm;rate=16000',
  };
}

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, Modality } from '@google/genai';
import { Message, ConnectionStatus } from './types';
import { encode, decode, decodeAudioData, createBlob } from './utils/audio';

// Custom Anime-style Components
const MahiruAvatar = ({ isSpeaking, isListening }: { isSpeaking: boolean; isListening: boolean }) => (
  <div className="relative w-64 h-64 mx-auto mb-8">
    <div className={`absolute inset-0 rounded-full bg-pink-200 opacity-20 animate-ping ${isSpeaking ? 'scale-110' : 'scale-0'}`}></div>
    <div className={`absolute inset-0 rounded-full border-4 border-pink-300 ${isListening ? 'animate-pulse' : ''}`}></div>
    <div className="relative w-full h-full rounded-full overflow-hidden border-4 border-white anime-glow bg-white flex items-center justify-center">
      {/* Placeholder for Anime Art - Using a cute SVG representaton */}
      <img 
        src="https://api.dicebear.com/7.x/avataaars/svg?seed=Mahiru&backgroundColor=ffdfbf&clothing=blazerAndShirt&clothingColor=ff92ad&hair=long&hairColor=724130&top=longHair&mouth=smile" 
        alt="Mahiru"
        className="w-full h-full object-cover"
      />
    </div>
    {isSpeaking && (
      <div className="absolute -bottom-2 left-1/2 transform -translate-x-1/2 bg-pink-500 text-white text-xs px-3 py-1 rounded-full animate-bounce">
        Bol rahi hoon... (Speaking...)
      </div>
    )}
  </div>
);

const App: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [status, setStatus] = useState<ConnectionStatus>(ConnectionStatus.DISCONNECTED);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [transcription, setTranscription] = useState("");

  const aiRef = useRef<any>(null);
  const sessionRef = useRef<any>(null);
  const audioContextsRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  const systemInstruction = `
    You are Mahiru, a kind, polite, and highly intelligent anime assistant. 
    You have a warm and supportive personality.
    CRITICAL: You are fluent in Hindi and English. If the user speaks in Hindi, you must reply in natural, fluent Hindi (Hinglish or Devanagari is fine, but spoken Hindi is preferred).
    You have vast knowledge about science, history, coding, and general facts.
    Always be helpful and slightly cheerful.
  `;

  const cleanup = useCallback(() => {
    if (sessionRef.current) {
      sessionRef.current.close?.();
      sessionRef.current = null;
    }
    sourcesRef.current.forEach(s => s.stop());
    sourcesRef.current.clear();
    nextStartTimeRef.current = 0;
  }, []);

  const startVoiceMode = async () => {
    try {
      setStatus(ConnectionStatus.CONNECTING);

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      aiRef.current = ai;

      const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const outputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      audioContextsRef.current = { input: inputCtx, output: outputCtx };

      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setStatus(ConnectionStatus.CONNECTED);
            setIsListening(true);

            const source = inputCtx.createMediaStreamSource(stream);
            const processor = inputCtx.createScriptProcessor(4096, 1, 1);

            processor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = createBlob(inputData);
              sessionPromise.then(session => {
                session.sendRealtimeInput({ media: pcmBlob });
              });
            };

            source.connect(processor);
            processor.connect(inputCtx.destination);
          },
          onmessage: async (msg) => {
            if (msg.serverContent?.outputTranscription) {
              setTranscription(prev => prev + msg.serverContent.outputTranscription.text);
            }

            if (msg.serverContent?.turnComplete) {
              setTranscription("");
            }

            const audioData = msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
            if (audioData) {
              setIsSpeaking(true);
              const outputCtx = audioContextsRef.current?.output;
              if (outputCtx) {
                nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
                const buffer = await decodeAudioData(decode(audioData), outputCtx, 24000, 1);
                const source = outputCtx.createBufferSource();
                source.buffer = buffer;
                source.connect(outputCtx.destination);
                source.addEventListener('ended', () => {
                  sourcesRef.current.delete(source);
                  if (sourcesRef.current.size === 0) setIsSpeaking(false);
                });
                source.start(nextStartTimeRef.current);
                nextStartTimeRef.current += buffer.duration;
                sourcesRef.current.add(source);
              }
            }

            if (msg.serverContent?.interrupted) {
              sourcesRef.current.forEach(s => s.stop());
              sourcesRef.current.clear();
              nextStartTimeRef.current = 0;
              setIsSpeaking(false);
            }
          },
          onerror: (e) => {
            console.error(e);
            setStatus(ConnectionStatus.ERROR);
          },
          onclose: () => {
            setStatus(ConnectionStatus.DISCONNECTED);
            setIsListening(false);
            setIsSpeaking(false);
          }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          systemInstruction,
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } }
          },
          outputAudioTranscription: {}
        }
      });

      sessionRef.current = await sessionPromise;
    } catch (err) {
      console.error(err);
      setStatus(ConnectionStatus.ERROR);
    }
  };

  const stopVoiceMode = () => {
    cleanup();
    setStatus(ConnectionStatus.DISCONNECTED);
    setIsListening(false);
    setIsSpeaking(false);
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 relative overflow-hidden">
      {/* Decorative Background Elements */}
      <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-pink-100 rounded-full blur-[100px] opacity-50"></div>
      <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-blue-100 rounded-full blur-[100px] opacity-50"></div>

      <main className="z-10 w-full max-w-2xl text-center">
        <header className="mb-8">
          <h1 className="text-4xl font-bold text-pink-600 mb-2">Mahiru AI</h1>
          <p className="text-pink-400 font-medium tracking-wide">Apki Digital Dost | आपकी डिजिटल दोस्त</p>
        </header>

        <div className="glass-panel p-8 rounded-3xl shadow-xl border border-white/50 relative">
          <MahiruAvatar isSpeaking={isSpeaking} isListening={isListening} />

          <div className="min-h-[60px] mb-8">
            {status === ConnectionStatus.CONNECTED ? (
              <div className="space-y-4">
                <div className="flex items-center justify-center gap-2">
                  <span className="flex h-3 w-3 relative">
                    <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-green-400 opacity-75"></span>
                    <span className="relative inline-flex rounded-full h-3 w-3 bg-green-500"></span>
                  </span>
                  <p className="text-green-600 font-semibold uppercase text-xs tracking-widest">Live: Mahiru is Listening</p>
                </div>
                {transcription && (
                  <p className="text-gray-700 italic bg-white/50 p-4 rounded-xl border border-pink-100 animate-in fade-in duration-500">
                    "{transcription}"
                  </p>
                )}
              </div>
            ) : status === ConnectionStatus.CONNECTING ? (
              <p className="text-pink-500 animate-pulse font-medium">Connecting to Mahiru...</p>
            ) : (
              <p className="text-gray-500 italic">Click the button below to start talking to Mahiru in Hindi or English!</p>
            )}
          </div>

          <div className="flex flex-col items-center gap-4">
            {status === ConnectionStatus.DISCONNECTED || status === ConnectionStatus.ERROR ? (
              <button
                onClick={startVoiceMode}
                className="group relative px-8 py-4 bg-pink-500 text-white rounded-full font-bold text-lg hover:bg-pink-600 transition-all active:scale-95 shadow-lg shadow-pink-200"
              >
                Start Conversation
                <div className="absolute inset-0 rounded-full bg-white/20 scale-0 group-hover:scale-100 transition-transform duration-300"></div>
              </button>
            ) : (
              <button
                onClick={stopVoiceMode}
                className="px-8 py-4 bg-gray-100 text-gray-600 rounded-full font-bold text-lg hover:bg-gray-200 transition-all active:scale-95 border border-gray-300"
              >
                End Session
              </button>
            )}

            {status === ConnectionStatus.ERROR && (
              <p className="text-red-500 text-sm mt-2 font-medium">Oops! Failed to connect. Please check your mic and try again.</p>
            )}
          </div>
        </div>

        <footer className="mt-12 text-pink-300 text-sm">
          <p>© 2024 Mahiru AI Assistant • Built with ❤️ for Anime fans</p>
        </footer>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, Modality } from '@google/genai';
import { Message, ConnectionStatus } from './types';
import { encode, decode, decodeAudioData, createBlob } from './utils/audio';

const MAHIRU_IMAGE_URL = "https://images.unsplash.com/photo-1578632292335-df3abbb0d586?q=80&w=1000&auto=format&fit=crop"; 
// Using a beautiful high-quality stylized anime art link

