        </header>

        <div className="glass-panel p-10 rounded-[40px] shadow-2xl relative overflow-hidden group">
          {/* Subtle inner decor */}
          <div className="absolute top-0 right-0 p-4 opacity-10 rotate-12 group-hover:rotate-45 transition-transform duration-1000">
             <svg width="60" height="60" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" className="text-pink-600">
                <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" fill="currentColor"/>
             </svg>
          </div>

          <MahiruAvatar isSpeaking={isSpeaking} isListening={isListening} />

          <div className="text-center space-y-6">
            <div className="min-h-[80px] flex flex-col justify-center">
              {status === ConnectionStatus.CONNECTED ? (
                <div className="space-y-4 animate-in fade-in slide-in-from-bottom-2 duration-700">
                   <div className="flex items-center justify-center gap-3">
                      <div className="flex space-x-1">
                        <div className="h-1.5 w-1.5 bg-green-500 rounded-full animate-bounce" style={{ animationDelay: '0s' }}></div>
                        <div className="h-1.5 w-1.5 bg-green-500 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }}></div>
                        <div className="h-1.5 w-1.5 bg-green-500 rounded-full animate-bounce" style={{ animationDelay: '0.4s' }}></div>
                      </div>
                      <span className="text-xs font-bold text-green-600 tracking-widest uppercase">Mahiru is Online</span>
                   </div>

                   {transcription && (
                     <div className="bg-pink-50/50 py-2 px-4 rounded-full inline-block border border-pink-100/50">
                        <p className="text-pink-600 text-sm italic font-medium">You: {transcription}</p>
                     </div>
                   )}

                   {lastResponse && (
                     <p className="text-gray-800 text-lg font-medium leading-relaxed max-w-md mx-auto">
                        "{lastResponse}"
                     </p>
                   )}
                </div>
              ) : status === ConnectionStatus.CONNECTING ? (
                <div className="space-y-3">
                  <div className="w-12 h-12 border-4 border-pink-200 border-t-pink-500 rounded-full animate-spin mx-auto"></div>
                  <p className="text-pink-500 font-bold">Calling Mahiru-chan...</p>
                </div>
              ) : (
                <div className="space-y-2">
                  <p className="text-gray-500 font-medium">"Namaste! Main Mahiru hoon. Kya hum baat kar sakte hain?"</p>
                  <p className="text-gray-400 text-sm italic">(Namaste! I am Mahiru. Can we talk?)</p>
                </div>
              )}
            </div>

            <div className="pt-4">
              {status === ConnectionStatus.DISCONNECTED || status === ConnectionStatus.ERROR ? (
                <button
                  onClick={startVoiceMode}
                  className="group relative px-12 py-5 bg-gradient-to-r from-pink-400 to-pink-500 text-white rounded-full font-bold text-xl hover:scale-105 transition-all active:scale-95 shadow-[0_10px_30px_-10px_rgba(244,114,182,0.5)] flex items-center gap-3 mx-auto overflow-hidden"
                >
                  <span className="relative z-10">Talk to Mahiru</span>
                  <svg className="w-6 h-6 relative z-10" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
                  </svg>
                  <div className="absolute inset-0 bg-white/20 translate-y-full group-hover:translate-y-0 transition-transform duration-300"></div>
                </button>
              ) : (
                <button
                  onClick={stopVoiceMode}
                  className="px-10 py-4 bg-white/80 text-gray-500 rounded-full font-bold text-lg hover:bg-white hover:text-pink-500 transition-all active:scale-95 border-2 border-pink-100 shadow-sm"
                >
                  Say Goodbye 👋
                </button>
              )}
            </div>

            {/* Quick Prompts in Hindi */}
            {status === ConnectionStatus.CONNECTED && !isSpeaking && (
               <div className="flex flex-wrap justify-center gap-2 pt-4 opacity-60 hover:opacity-100 transition-opacity">
                  {["Aap kaise ho?", "Kuch sunao", "Hindi mein baat karo"].map((text) => (
                    <button 
                      key={text}
                      className="text-xs bg-white/50 border border-pink-100 px-3 py-1 rounded-full text-pink-500 hover:bg-pink-500 hover:text-white transition-colors"
                    >
                      {text}
                    </button>
                  ))}
               </div>
            )}
          </div>
        </div>

        <footer className="mt-12 text-center space-y-1">
          <div className="h-px w-24 bg-pink-200 mx-auto mb-4"></div>
          <p className="text-pink-300 font-bold text-sm">Designed for Elegance</p>
          <p className="text-pink-200 text-[10px] uppercase tracking-widest">Advanced Neural Companion Model</p>
        </footer>
      </main>
    </div>
