  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [errorMessage, setErrorMessage] = useState("");
  const [voiceName, setVoiceName] = useState("Kore");
  const [inputText, setInputText] = useState("");
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);

  const sessionRef = useRef<any>(null);
  const audioContextsRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const chatEndRef = useRef<HTMLDivElement>(null);

  const systemInstruction = `
    Identity: You are Mahiru, a highly intelligent, polite, and cheerful anime girl AI. 
    CRITICAL RULE: You MUST speak ONLY in Hindi. Do not use English even if the user speaks English. Always reply in sweet, helpful, and natural spoken Hindi.
    Role: You are the best AI ever made. You provide high-quality answers to any question about science, coding, history, or life.
    Personality: Helpful, slightly playful, and respectful. You are the user's best friend.
  `;

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatHistory]);

  const cleanup = useCallback(() => {
    if (sessionRef.current) {
      sessionRef.current.close?.();
      sessionRef.current = null;
    }
    sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
    sourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setIsListening(false);
    setIsSpeaking(false);
    setIsProcessing(false);

    if (audioContextsRef.current) {
      audioContextsRef.current.input.close().catch(() => {});
      audioContextsRef.current.output.close().catch(() => {});
      audioContextsRef.current = null;
    }
  }, []);

  const handleTranslate = async (text: string) => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Translate this Hindi text to English. Return only the translated text: "${text}"`,
    });
    return response.text?.trim() || "";
  };

  const handleSendMessage = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!inputText.trim()) return;

    const userHindi = inputText.trim();
    setInputText("");
    setIsProcessing(true);

    // 1. Get Translation
    let userEnglish = "";
    try {
      userEnglish = await handleTranslate(userHindi);
    } catch (err) {
      console.error("Translation error", err);
    }

    const newUserMsg: ChatMessage = { id: Date.now().toString(), hindi: userHindi, english: userEnglish, sender: 'user' };
    setChatHistory(prev => [...prev, newUserMsg]);

    // 2. Get Mahiru's Response (Text + Audio)
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userHindi,
        config: {
          systemInstruction,
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName } } }
        }
      });

      const responseHindi = response.text || "Mafi chahti hoon, main samajh nahi payi.";
      const mahiruMsg: ChatMessage = { id: (Date.now() + 1).toString(), hindi: responseHindi, sender: 'mahiru' };
      setChatHistory(prev => [...prev, mahiruMsg]);

      // Play Audio
      const audioData = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData)?.inlineData?.data;
      if (audioData) {
        setIsSpeaking(true);
        const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        const buffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = buffer;
        source.connect(ctx.destination);
        source.onended = () => setIsSpeaking(false);
        source.start(0);
      }
    } catch (err) {
      console.error(err);
      setErrorMessage("Baat karne mein dikkat aa rahi hai.");
      setStatus(ConnectionStatus.ERROR);
    } finally {
      setIsProcessing(false);
    }
  };

