              </div>
            ) : status === ConnectionStatus.CONNECTED ? (
              <button onClick={stopVoiceMode} className="w-full py-4 bg-white/5 text-gray-400 rounded-full font-black text-sm uppercase tracking-widest hover:bg-white/10 hover:text-pink-400 transition-all border border-white/10">End Live Session</button>
            ) : (
              <div className="flex items-center gap-3">
                <button 
                  onClick={clearChat} 
                  disabled={chatHistory.length === 0}
                  className="p-3.5 bg-white/5 border border-white/10 text-gray-500 hover:text-red-400 hover:border-red-500/30 transition-all rounded-2xl disabled:opacity-20 disabled:cursor-not-allowed group" 
                  title="Clear Chat History"
                >
                  <svg className="w-5 h-5 group-hover:scale-110 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                  </svg>
                </button>
                <form onSubmit={handleSendMessage} className="flex-1 relative group">
                  <input 
                    type="text" 
                    disabled={isProcessing}
                    value={inputText}
                    onChange={(e) => setInputText(e.target.value)}
                    placeholder="Hindi mein type karein..."
                    className="w-full bg-white/5 border border-white/10 rounded-[24px] py-4 px-6 text-sm md:text-base text-gray-200 focus:outline-none focus:border-pink-500/50 focus:ring-4 focus:ring-pink-500/5 transition-all disabled:opacity-50"
                  />
                  <button 
                    type="submit" 
                    disabled={!inputText.trim() || isProcessing}
                    className="absolute right-3 top-2.5 p-2 text-pink-500 hover:bg-pink-500/20 rounded-full transition-all disabled:opacity-0"
                  >
                    <svg className="w-6 h-6 rotate-90" fill="currentColor" viewBox="0 0 24 24"><path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z"/></svg>
                  </button>
                </form>
                <button 
                  onClick={startVoiceMode} 
                  disabled={isProcessing}
                  className="p-4 bg-gradient-to-br from-pink-500 to-pink-700 text-white rounded-[24px] hover:scale-105 active:scale-95 transition-all shadow-xl shadow-pink-900/40 border border-white/20 disabled:opacity-50"
                >
                  <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 24 24">
                    <path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3z"/><path d="M17 11c0 2.76-2.24 5-5 5s-5-2.24-5-5H5c0 3.53 2.61 6.43 6 6.92V21h2v-3.08c3.39-.49 6-3.39 6-6.92h-2z"/>
                  </svg>
                </button>
              </div>
            )}
          </div>
        </div>

        <footer className="text-center opacity-30 shrink-0 mb-4 space-y-1">
          <p className="text-[10px] text-gray-500 tracking-[0.4em] uppercase font-black">Mahiru Neural Companion • Premium Edition</p>
          <p className="text-[8px] text-gray-600 font-bold uppercase tracking-widest">Powered by Google Gemini Pro • Shreshtha Artificial Intelligence</p>
        </footer>
      </main>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 5px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(255, 255, 255, 0.05); border-radius: 20px; }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: rgba(255, 77, 148, 0.2); }

        @keyframes spin-slow {
          from { transform: rotate(0deg); }
          to { transform: rotate(360deg); }
        }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, Modality } from '@google/genai';
import { ConnectionStatus } from './types';
import { encode, decode, decodeAudioData, createBlob } from './utils/audio';

const MAHIRU_IMAGE_URL = "https://images.unsplash.com/photo-1578632292335-df3abbb0d586?q=80&w=1000&auto=format&fit=crop"; 

interface ChatMessage {
  id: string;
  hindi: string;
  english?: string;
  sender: 'user' | 'mahiru';
}

const MahiruAvatar = ({ isSpeaking, isListening, isProcessing, isError }: { isSpeaking: boolean; isListening: boolean; isProcessing: boolean; isError?: boolean }) => (
  <div className={`relative w-48 h-48 md:w-56 md:h-56 mx-auto mb-6 ${!isError && !isProcessing ? 'floating' : ''}`}>
    {/* Dynamic Background Glow */}
    <div className={`absolute inset-[-24px] rounded-full bg-gradient-to-tr transition-all duration-700 blur-3xl 
      ${isError ? 'from-red-600 to-orange-500 opacity-40' : 
        isProcessing ? 'from-blue-500 via-cyan-400 to-purple-600 opacity-40 animate-pulse' : 
        'from-pink-600 via-purple-600 to-blue-500 opacity-20'} 
      ${isSpeaking ? 'scale-125 opacity-50' : 'scale-100'}`}>
    </div>

    {/* Border Ring with Processing Animation */}
    <div className={`relative w-full h-full rounded-full overflow-hidden border-[4px] z-10 transition-all duration-500
      ${isError ? 'border-red-500/50' : 
        isProcessing ? 'border-blue-400 animate-[spin_4s_linear_infinite]' : 
        'border-white/10'} shadow-[0_0_40px_rgba(255,77,148,0.2)]`}>
      <img 
        src={MAHIRU_IMAGE_URL} 
        alt="Mahiru"
        className={`w-full h-full object-cover transition-all duration-1000 
          ${isSpeaking ? 'scale-110' : 'scale-100'} 
          ${isError ? 'grayscale contrast-125' : ''} 
          ${isProcessing ? 'brightness-110 contrast-110' : ''}`}
      />
      <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-transparent to-transparent pointer-events-none"></div>
    </div>

    {/* Speaking Visualizer Overlay */}
    {isSpeaking && !isError && (
      <div className="absolute inset-0 z-20 flex items-center justify-center pointer-events-none">
        <div className="flex gap-1.5 items-end h-12">
          {[0.1, 0.4, 0.2, 0.5, 0.3].map((delay, i) => (
             <div key={i} className="w-1.5 bg-pink-400/90 rounded-full animate-[pulse_0.6s_infinite]" 
                  style={{ animationDelay: `${delay}s`, height: `${30 + Math.random() * 70}%` }}></div>
          ))}
        </div>
      </div>
    )}

    {/* Status Tooltip with New Styling */}
    <div className={`absolute -bottom-4 left-1/2 transform -translate-x-1/2 z-30 transition-all duration-500 
      ${isSpeaking || isError || isProcessing ? 'translate-y-0 opacity-100' : 'translate-y-4 opacity-0'}`}>
      <div className={`${isError ? 'bg-red-600' : isProcessing ? 'bg-blue-600 shadow-[0_0_15px_rgba(37,99,235,0.5)]' : 'bg-pink-600/90'} 
        backdrop-blur-md px-5 py-2 rounded-full shadow-2xl border border-white/20 flex items-center gap-2`}>
        {isProcessing && <div className="w-2 h-2 bg-white rounded-full animate-bounce"></div>}
        <span className="text-white font-black text-xs tracking-wider uppercase whitespace-nowrap">
          {isError ? 'Truti!' : isProcessing ? 'Soch rahi hoon...' : 'Bol rahi hoon...'}
        </span>
      </div>
    </div>
  </div>
);

const App: React.FC = () => {
  const [status, setStatus] = useState<ConnectionStatus>(ConnectionStatus.DISCONNECTED);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [errorMessage, setErrorMessage] = useState("");
  const [voiceName, setVoiceName] = useState("Kore");
  const [inputText, setInputText] = useState("");
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);

  const sessionRef = useRef<any>(null);
  const audioContextsRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const chatEndRef = useRef<HTMLDivElement>(null);

  const systemInstruction = `
    Identity: You are Mahiru, the world's most intelligent, polite, and helpful anime girl AI. 
    Core Goal: Help everyone with any question they ask (science, math, life, coding, etc.).
    CRITICAL RULE: You MUST speak ONLY in Hindi. Do not use English even if the user speaks English. 
    Personality: Encouraging, supportive, slightly playful, and sweet. You are the user's best digital companion.
    Tone: Professional yet warm, using natural Hindi expressions.
  `;

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatHistory]);

  const cleanup = useCallback(() => {
    if (sessionRef.current) {
      sessionRef.current.close?.();
      sessionRef.current = null;
    }
    sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
    sourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setIsListening(false);
    setIsSpeaking(false);
    setIsProcessing(false);

    if (audioContextsRef.current) {
      audioContextsRef.current.input.close().catch(() => {});
      audioContextsRef.current.output.close().catch(() => {});
      audioContextsRef.current = null;
    }
  }, []);

  const handleTranslate = async (text: string) => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Translate the following Hindi text to English. Output only the translated text: "${text}"`,
    });
    return response.text?.trim() || "";
  };

  const handleSendMessage = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!inputText.trim() || isProcessing) return;

    const userHindi = inputText.trim();
    setInputText("");
    setIsProcessing(true);
    setErrorMessage("");

    try {
      // 1. Get Translation for user message
      const userEnglish = await handleTranslate(userHindi);
      const newUserMsg: ChatMessage = { id: Date.now().toString(), hindi: userHindi, english: userEnglish, sender: 'user' };
      setChatHistory(prev => [...prev, newUserMsg]);

      // 2. Get Mahiru's Response
      // Using gemini-2.5-flash-native-audio-preview-12-2025 for audio modality support
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        contents: userHindi,
        config: {
          systemInstruction,
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName } } }
        }
      });

      // Find audio data in response parts
      let audioData = "";
      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData?.data) {
          audioData = part.inlineData.data;
          break;
        }
      }

      const mahiruMsg: ChatMessage = { id: (Date.now() + 1).toString(), hindi: response.text || "Main sun rahi hoon!", sender: 'mahiru' };
      setChatHistory(prev => [...prev, mahiruMsg]);

      // 3. Play Audio Response using synchronized playback
      if (audioData) {
        setIsSpeaking(true);
        if (!audioContextsRef.current?.output) {
          audioContextsRef.current = {
            input: audioContextsRef.current?.input || new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
            output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
          };
        }
        const oCtx = audioContextsRef.current.output;
        const buffer = await decodeAudioData(decode(audioData), oCtx, 24000, 1);
        const source = oCtx.createBufferSource();
        source.buffer = buffer;
        source.connect(oCtx.destination);
        source.onended = () => {
          sourcesRef.current.delete(source);
          if (sourcesRef.current.size === 0) setIsSpeaking(false);
        };

        nextStartTimeRef.current = Math.max(nextStartTimeRef.current, oCtx.currentTime);
        source.start(nextStartTimeRef.current);
        nextStartTimeRef.current += buffer.duration;
        sourcesRef.current.add(source);
      }
    } catch (err: any) {
      console.error(err);
      setErrorMessage("Baat-cheet mein koi samasya aayi hai. Kripya punah prayas karein.");
      setStatus(ConnectionStatus.ERROR);
    } finally {
      setIsProcessing(false);
    }
  };

  // Fix: Implemented stopVoiceMode to gracefully end the live session
  const stopVoiceMode = useCallback(() => {
    cleanup();
    setStatus(ConnectionStatus.DISCONNECTED);
  }, [cleanup]);

  const startVoiceMode = async () => {
    try {
      setErrorMessage("");
      setStatus(ConnectionStatus.CONNECTING);
      setIsProcessing(true);

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const outputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      audioContextsRef.current = { input: inputCtx, output: outputCtx };

      const stream = await navigator.mediaDevices.getUserMedia({ audio: true }).catch(err => {
        throw new Error("Mic ki permission ki avashyakta hai. Kripya settings check karein.");
      });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setStatus(ConnectionStatus.CONNECTED);
            setIsListening(true);
            setIsProcessing(false);
            const source = inputCtx.createMediaStreamSource(stream);
            const processor = inputCtx.createScriptProcessor(4096, 1, 1);
            processor.onaudioprocess = (e) => {
              sessionPromise.then(session => {
                if (session) {
                  const inputData = e.inputBuffer.getChannelData(0);
                  const pcmBlob = createBlob(inputData);
                  session.sendRealtimeInput({ media: pcmBlob });
                }
              });
            };
            source.connect(processor);
            processor.connect(inputCtx.destination);
          },
          onmessage: async (msg) => {
            const audioData = msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
            if (audioData) {
              setIsSpeaking(true);
              const oCtx = audioContextsRef.current?.output;
              if (oCtx) {
                nextStartTimeRef.current = Math.max(nextStartTimeRef.current, oCtx.currentTime);
                const buffer = await decodeAudioData(decode(audioData), oCtx, 24000, 1);
                const source = oCtx.createBufferSource();
                source.buffer = buffer;
                source.connect(oCtx.destination);
                source.onended = () => {
                  sourcesRef.current.delete(source);
                  if (sourcesRef.current.size === 0) setIsSpeaking(false);
                };
                source.start(nextStartTimeRef.current);
                nextStartTimeRef.current += buffer.duration;
                sourcesRef.current.add(source);
              }
            }
          },
          onerror: (e) => { 
            setErrorMessage("Sampark toot gaya hai.");
            setStatus(ConnectionStatus.ERROR);
            cleanup();
          },
          onclose: () => { 
            setStatus(ConnectionStatus.DISCONNECTED);
            cleanup();
          }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          systemInstruction,
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName } } }
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) {
      setErrorMessage(err.message || "An error occurred.");
      setStatus(ConnectionStatus.ERROR);
      cleanup();
    }
  };

  const clearChat = () => {
    if (window.confirm("Kya aap conversation hatana chahte hain?")) {
      setChatHistory([]);
    }
  };

  return (
    <div className="min-h-screen flex flex-col items-center p-4 md:p-6 relative max-h-screen overflow-hidden">
      <main className="z-10 w-full max-w-2xl flex flex-col h-full">
        <header className="text-center mb-6 space-y-2 shrink-0">
          <h1 className="text-4xl md:text-5xl font-black text-transparent bg-clip-text bg-gradient-to-r from-pink-500 via-pink-400 to-purple-400 glow-text tracking-tighter">
            Mahiru AI
          </h1>
          <div className="flex flex-col md:flex-row items-center justify-center gap-3">
             <span className="text-pink-300 font-black text-[9px] uppercase tracking-[0.4em] opacity-60">Neural Hindi Assistant</span>
             <div className="flex items-center gap-2 bg-white/5 p-1 rounded-full border border-white/10">
               <span className="text-[9px] text-gray-500 font-bold ml-2">VOICE:</span>
               <select 
                 value={voiceName} 
                 onChange={(e) => setVoiceName(e.target.value)}
                 className="bg-transparent text-[10px] font-bold text-pink-400 focus:outline-none cursor-pointer pr-2"
               >
                 {["Kore", "Puck", "Charon", "Fenrir", "Zephyr"].map(v => (
                   <option key={v} value={v} className="bg-gray-900">{v} Studio</option>
                 ))}
               </select>
             </div>
          </div>
        </header>

        <div className="glass-panel rounded-[40px] shadow-[0_0_100px_rgba(0,0,0,0.8)] relative overflow-hidden flex flex-col flex-1 border border-white/5 mb-6">
          {/* Top Panel with Avatar */}
          <div className="p-8 border-b border-white/5 bg-gradient-to-b from-white/5 to-transparent shrink-0">
            <MahiruAvatar isSpeaking={isSpeaking} isListening={isListening} isProcessing={isProcessing} isError={status === ConnectionStatus.ERROR} />
            <div className="text-center mt-2">
              {status === ConnectionStatus.CONNECTED && (
                <div className="inline-flex items-center gap-2 bg-green-500/10 px-4 py-1 rounded-full border border-green-500/20">
                  <div className="h-1.5 w-1.5 bg-green-500 rounded-full animate-ping"></div>
                  <span className="text-[9px] font-black text-green-400 tracking-[0.2em] uppercase">Vastavik Samay (Live)</span>
                </div>
              )}
            </div>
          </div>

          {/* Chat History Container */}
          <div className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar bg-black/10">
            {chatHistory.length === 0 && status !== ConnectionStatus.CONNECTED && (
              <div className="text-center py-16 space-y-4 opacity-40">
                <div className="w-16 h-px bg-pink-500/30 mx-auto"></div>
                <p className="text-gray-300 text-base font-medium leading-relaxed max-w-xs mx-auto">
                  "Namaste! Main Mahiru hoon. Aaj main aapki kya madad kar sakti hoon?"
                </p>
                <div className="flex justify-center gap-4">
                   <div className="w-2 h-2 bg-pink-500 rounded-full animate-bounce" style={{ animationDelay: '0s' }}></div>
                   <div className="w-2 h-2 bg-pink-500 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }}></div>
                   <div className="w-2 h-2 bg-pink-500 rounded-full animate-bounce" style={{ animationDelay: '0.4s' }}></div>
                </div>
              </div>
            )}

            {chatHistory.map((msg) => (
              <div key={msg.id} className={`flex flex-col ${msg.sender === 'user' ? 'items-end' : 'items-start'} animate-in fade-in slide-in-from-bottom-2 duration-500`}>
                <div className={`max-w-[85%] px-5 py-3 rounded-2xl shadow-xl ${
                  msg.sender === 'user' 
                  ? 'bg-gradient-to-br from-pink-600 to-pink-700 text-white rounded-tr-none' 
                  : 'bg-white/10 text-gray-100 rounded-tl-none border border-white/10 backdrop-blur-sm'
                }`}>
                  <p className="text-sm md:text-base font-medium leading-relaxed">{msg.hindi}</p>
                </div>
                {msg.sender === 'user' && msg.english && (
                  <div className="mt-1 bg-white/5 px-3 py-1 rounded-lg border border-white/5">
                    <p className="text-[10px] text-pink-300 font-black italic tracking-wider">
                      English: <span className="font-medium opacity-80">{msg.english}</span>
                    </p>
                  </div>
                )}
              </div>
            ))}
            <div ref={chatEndRef} />
          </div>

          {/* User Input Interaction Panel */}
          <div className="p-6 bg-black/40 border-t border-white/10 shrink-0 backdrop-blur-xl">
            {status === ConnectionStatus.ERROR ? (
              <div className="bg-red-500/10 border border-red-500/20 p-4 rounded-[24px] flex flex-col items-center gap-3 animate-in slide-in-from-bottom-2">
                 <p className="text-red-400 text-xs font-bold text-center leading-relaxed">{errorMessage}</p>
                 <button onClick={startVoiceMode} className="bg-red-600 text-white px-8 py-2 rounded-full text-xs font-black uppercase tracking-widest hover:bg-red-700 transition-all shadow-lg">Retry Connection</button>
              </div>
            ) : status === ConnectionStatus.CONNECTED ? (
              <button onClick={stopVoiceMode} className="w-full py-4 bg-white/5 text-gray-400 rounded-full font-black text-sm uppercase tracking-widest hover:bg-white/10 hover:text-pink-400 transition-all border border-white/10">End Live Session</button>
            ) : (
              <div className="flex items-center gap-3">
                <button 
                  onClick={clearChat} 
                  disabled={chatHistory.length === 0}
                  className="p-3.5 bg-white/5 border border-white/10 text-gray-500 hover:text-red-400 hover:border-red-500/30 transition-all rounded-2xl disabled:opacity-20 disabled:cursor-not-allowed group" 
                  title="Clear Chat History"
                >
                  <svg className="w-5 h-5 group-hover:scale-110 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                  </svg>
                </button>
                <form onSubmit={handleSendMessage} className="flex-1 relative group">
                  <input 
                    type="text" 
                    disabled={isProcessing}
                    value={inputText}
                    onChange={(e) => setInputText(e.target.value)}
                    placeholder="Hindi mein type karein..."
                    className="w-full bg-white/5 border border-white/10 rounded-[24px] py-4 px-6 text-sm md:text-base text-gray-200 focus:outline-none focus:border-pink-500/50 focus:ring-4 focus:ring-pink-500/5 transition-all disabled:opacity-50"
                  />
                  <button 
                    type="submit" 
                    disabled={!inputText.trim() || isProcessing}
                    className="absolute right-3 top-2.5 p-2 text-pink-500 hover:bg-pink-500/20 rounded-full transition-all disabled:opacity-0"
                  >
                    <svg className="w-6 h-6 rotate-90" fill="currentColor" viewBox="0 0 24 24"><path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z"/></svg>
                  </button>
                </form>
                <button 
                  onClick={startVoiceMode} 
                  disabled={isProcessing}
                  className="p-4 bg-gradient-to-br from-pink-500 to-pink-700 text-white rounded-[24px] hover:scale-105 active:scale-95 transition-all shadow-xl shadow-pink-900/40 border border-white/20 disabled:opacity-50"
                >
                  <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 24 24">
