export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, Modality } from '@google/genai';
import { ConnectionStatus } from './types';
import { encode, decode, decodeAudioData, createBlob } from './utils/audio';

const MAHIRU_IMAGE_URL = "https://images.unsplash.com/photo-1578632292335-df3abbb0d586?q=80&w=1000&auto=format&fit=crop"; 

interface ChatMessage {
  id: string;
  primaryText: string;
  secondaryText?: string;
  sender: 'user' | 'mahiru';
}

interface UserProfile {
  name: string;
  language: 'hindi' | 'english';
  voice: string;
}

const MahiruAvatar = ({ isSpeaking, isListening, isProcessing, isError }: { isSpeaking: boolean; isListening: boolean; isProcessing: boolean; isError?: boolean }) => (
  <div className={`relative w-40 h-40 md:w-48 md:h-48 mx-auto mb-4 ${!isError && !isProcessing ? 'floating' : ''}`}>
    <div className={`absolute inset-[-20px] rounded-full bg-gradient-to-tr transition-all duration-700 blur-3xl 
      ${isError ? 'from-red-600 to-orange-500 opacity-40' : 
        isProcessing ? 'from-blue-500 via-cyan-400 to-purple-600 opacity-40 animate-pulse' : 
        'from-pink-600 via-purple-600 to-blue-500 opacity-20'} 
      ${isSpeaking ? 'scale-125 opacity-50' : 'scale-100'}`}>
    </div>

    <div className={`relative w-full h-full rounded-full overflow-hidden border-[4px] z-10 transition-all duration-500
      ${isError ? 'border-red-500/50' : 
        isProcessing ? 'border-blue-400 animate-[spin_4s_linear_infinite]' : 
        'border-white/10'} shadow-[0_0_40px_rgba(255,77,148,0.2)]`}>
      <img src={MAHIRU_IMAGE_URL} alt="Mahiru" className={`w-full h-full object-cover transition-all duration-1000 ${isSpeaking ? 'scale-110' : 'scale-100'} ${isError ? 'grayscale contrast-125' : ''}`} />
      <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-transparent to-transparent pointer-events-none"></div>
    </div>

    {isSpeaking && !isError && (
      <div className="absolute inset-0 z-20 flex items-center justify-center pointer-events-none">
        <div className="flex gap-1 items-end h-8">
          {[0.1, 0.4, 0.2, 0.5, 0.3].map((delay, i) => (
             <div key={i} className="w-1 bg-pink-400/90 rounded-full animate-[pulse_0.6s_infinite]" style={{ animationDelay: `${delay}s`, height: `${30 + Math.random() * 70}%` }}></div>
          ))}
        </div>
      </div>
    )}
  </div>
);

const App: React.FC = () => {
  const [userProfile, setUserProfile] = useState<UserProfile | null>(() => {
    const saved = localStorage.getItem('mahiru_profile');
    return saved ? JSON.parse(saved) : null;
  });
  const [showSettings, setShowSettings] = useState(false);
  const [status, setStatus] = useState<ConnectionStatus>(ConnectionStatus.DISCONNECTED);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [errorMessage, setErrorMessage] = useState("");
  const [inputText, setInputText] = useState("");
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);

  const sessionRef = useRef<any>(null);
  const audioContextsRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const chatEndRef = useRef<HTMLDivElement>(null);

  const currentLang = userProfile?.language || 'hindi';
  const currentVoice = userProfile?.voice || 'Kore';

  const systemInstruction = `
    Identity: You are Mahiru, a polite and cheerful anime girl AI. 
    User Context: The user's name is ${userProfile?.name || 'Friend'}.
    CRITICAL RULE: You MUST speak ONLY in ${currentLang === 'hindi' ? 'Hindi' : 'English'}.
    Personality: Encouraging, sweet, and highly intelligent.
    Tone: Warm and professional.
  `;

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatHistory]);

  const cleanup = useCallback(() => {
    if (sessionRef.current) { sessionRef.current.close?.(); sessionRef.current = null; }
    sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
    sourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setIsListening(false);
    setIsSpeaking(false);
    setIsProcessing(false);
    if (audioContextsRef.current) {
      audioContextsRef.current.input.close().catch(() => {});
      audioContextsRef.current.output.close().catch(() => {});
      audioContextsRef.current = null;
    }
  }, []);

  const handleTranslate = async (text: string, targetLang: string) => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Translate the following text to ${targetLang}. Output only the translated text: "${text}"`,
    });
    return response.text?.trim() || "";
  };

  const handleSendMessage = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!inputText.trim() || isProcessing) return;

    const userText = inputText.trim();
    setInputText("");
    setIsProcessing(true);
    setErrorMessage("");

    try {
      const secondaryText = await handleTranslate(userText, currentLang === 'hindi' ? 'English' : 'Hindi');
      const newUserMsg: ChatMessage = { id: Date.now().toString(), primaryText: userText, secondaryText, sender: 'user' };
      setChatHistory(prev => [...prev, newUserMsg]);

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        contents: userText,
        config: {
          systemInstruction,
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: currentVoice } } }
        }
      });

      const mahiruText = response.text || (currentLang === 'hindi' ? "Mafi chahti hoon!" : "I'm sorry!");
      const mahiruSecText = await handleTranslate(mahiruText, currentLang === 'hindi' ? 'English' : 'Hindi');
      const mahiruMsg: ChatMessage = { id: (Date.now() + 1).toString(), primaryText: mahiruText, secondaryText: mahiruSecText, sender: 'mahiru' };
      setChatHistory(prev => [...prev, mahiruMsg]);

      const audioData = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData)?.inlineData?.data;
      if (audioData) {
        setIsSpeaking(true);
        const ctx = audioContextsRef.current?.output || new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        const buffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = buffer;
        source.connect(ctx.destination);
        source.onended = () => { sourcesRef.current.delete(source); if (sourcesRef.current.size === 0) setIsSpeaking(false); };
        nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
        source.start(nextStartTimeRef.current);
        nextStartTimeRef.current += buffer.duration;
        sourcesRef.current.add(source);
      }
    } catch (err: any) {
      setErrorMessage(currentLang === 'hindi' ? "Kuch galat hua." : "Something went wrong.");
      setStatus(ConnectionStatus.ERROR);
    } finally {
      setIsProcessing(false);
    }
  };

  const startVoiceMode = async () => {
    try {
      setErrorMessage("");
      setStatus(ConnectionStatus.CONNECTING);
      setIsProcessing(true);
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const outputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      audioContextsRef.current = { input: inputCtx, output: outputCtx };
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => { setStatus(ConnectionStatus.CONNECTED); setIsListening(true); setIsProcessing(false);
            const source = inputCtx.createMediaStreamSource(stream);
            const processor = inputCtx.createScriptProcessor(4096, 1, 1);
            processor.onaudioprocess = (e) => {
              sessionPromise.then(session => {
                if (session) {
                  const inputData = e.inputBuffer.getChannelData(0);
                  const pcmBlob = createBlob(inputData);
                  session.sendRealtimeInput({ media: pcmBlob });
                }
              });
            };
            source.connect(processor);
            processor.connect(inputCtx.destination);
          },
          onmessage: async (msg) => {
            const audioData = msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
            if (audioData) {
              setIsSpeaking(true);
              const buffer = await decodeAudioData(decode(audioData), outputCtx, 24000, 1);
              const source = outputCtx.createBufferSource();
              source.buffer = buffer;
              source.connect(outputCtx.destination);
              source.onended = () => { sourcesRef.current.delete(source); if (sourcesRef.current.size === 0) setIsSpeaking(false); };
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              sourcesRef.current.add(source);
            }
          },
          onerror: () => { setErrorMessage("Connection error"); setStatus(ConnectionStatus.ERROR); cleanup(); },
          onclose: () => { setStatus(ConnectionStatus.DISCONNECTED); cleanup(); }
        },
        config: { responseModalities: [Modality.AUDIO], systemInstruction, speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: currentVoice } } } }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { setErrorMessage(err.message); setStatus(ConnectionStatus.ERROR); cleanup(); }
  };

  const updateProfile = (updates: Partial<UserProfile>) => {
    const newProfile = { ...userProfile!, ...updates };
    setUserProfile(newProfile);
    localStorage.setItem('mahiru_profile', JSON.stringify(newProfile));
  };

  if (!userProfile) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6 bg-[#0a0a0c]">
        <div className="glass-panel p-10 rounded-[40px] w-full max-w-md text-center space-y-8 animate-in zoom-in-95 duration-700">
          <header className="space-y-2">
            <h1 className="text-4xl font-black text-pink-500 glow-text">Mahiru AI</h1>
            <p className="text-gray-400 text-sm">Aapka digital saathi (Your digital companion)</p>
          </header>
          <div className="relative">
            <div className="absolute inset-0 bg-pink-500/10 blur-2xl rounded-full"></div>
            <img src={MAHIRU_IMAGE_URL} className="w-32 h-32 rounded-full mx-auto border-2 border-pink-500/30 relative z-10" alt="Mahiru" />
          </div>
          <div className="space-y-4">
            <input 
              type="text" 
              placeholder="Aapka Naam? (Your Name)" 
              className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white focus:outline-none focus:border-pink-500 transition-all text-center"
              onKeyDown={(e) => {
                if (e.key === 'Enter') {
                  const name = (e.target as HTMLInputElement).value.trim();
                  if (name) updateProfile({ name, language: 'hindi', voice: 'Kore' });
                }
              }}
            />
            <p className="text-[10px] text-gray-500 uppercase tracking-widest font-bold">Press Enter to Begin</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col items-center p-4 md:p-6 relative max-h-screen overflow-hidden">
      <main className="z-10 w-full max-w-2xl flex flex-col h-full">
        {/* Navigation Bar */}
        <header className="flex items-center justify-between mb-4 shrink-0 px-2">
          <div className="flex flex-col">
            <h1 className="text-2xl md:text-3xl font-black text-pink-500 glow-text">Mahiru AI</h1>
            <span className="text-[10px] font-bold text-gray-500 uppercase tracking-tighter">Hi, {userProfile.name}</span>
          </div>
          <div className="flex items-center gap-3">
            <button 
              onClick={() => setShowSettings(!showSettings)}
              className="p-3 bg-white/5 border border-white/10 rounded-2xl text-pink-400 hover:bg-white/10 transition-all"
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
            </button>
          </div>
        </header>

        {/* Settings Modal (Overlay) */}
        {showSettings && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-black/60 backdrop-blur-sm animate-in fade-in duration-300">
            <div className="glass-panel p-8 rounded-[32px] w-full max-w-sm space-y-6 border border-pink-500/20 shadow-2xl">
              <div className="flex items-center justify-between border-b border-white/5 pb-4">
                <h2 className="text-xl font-black text-white">Settings</h2>
                <button onClick={() => setShowSettings(false)} className="text-gray-500 hover:text-white">✕</button>
              </div>

              <div className="space-y-4">
                <div className="space-y-2">
                  <label className="text-xs font-bold text-gray-500 uppercase tracking-widest">Language / Bhasha</label>
                  <div className="grid grid-cols-2 gap-2">
                    <button 
                      onClick={() => updateProfile({ language: 'hindi' })}
                      className={`py-3 rounded-xl font-bold text-sm transition-all border ${currentLang === 'hindi' ? 'bg-pink-600 text-white border-pink-400' : 'bg-white/5 text-gray-400 border-white/10'}`}
                    >हिंदी</button>
                    <button 
                      onClick={() => updateProfile({ language: 'english' })}
                      className={`py-3 rounded-xl font-bold text-sm transition-all border ${currentLang === 'english' ? 'bg-pink-600 text-white border-pink-400' : 'bg-white/5 text-gray-400 border-white/10'}`}
                    >English</button>
                  </div>
                </div>

                <div className="space-y-2">
                  <label className="text-xs font-bold text-gray-500 uppercase tracking-widest">Voice Selection</label>
                  <select 
                    value={currentVoice}
                    onChange={(e) => updateProfile({ voice: e.target.value })}
                    className="w-full bg-white/5 border border-white/10 rounded-xl py-3 px-4 text-white focus:outline-none"
                  >
                    {["Kore", "Puck", "Charon", "Fenrir", "Zephyr"].map(v => <option key={v} value={v} className="bg-[#1a1a1c]">{v} Studio</option>)}
                  </select>
                </div>

                <div className="pt-4 space-y-2">
                   <button 
                    onClick={() => { if(confirm("Reset App?")) { localStorage.clear(); window.location.reload(); } }}
                    className="w-full py-3 bg-red-500/10 text-red-400 rounded-xl text-xs font-black uppercase tracking-widest hover:bg-red-500/20 transition-all border border-red-500/20"
                  >Reset Everything</button>
                </div>
              </div>
            </div>
          </div>
        )}

        <div className="glass-panel rounded-[40px] shadow-2xl relative overflow-hidden flex flex-col flex-1 border border-white/5 mb-6">
          <div className="p-6 border-b border-white/5 bg-gradient-to-b from-white/5 to-transparent shrink-0">
            <MahiruAvatar isSpeaking={isSpeaking} isListening={isListening} isProcessing={isProcessing} isError={status === ConnectionStatus.ERROR} />
            <div className="text-center mt-2">
              {status === ConnectionStatus.CONNECTED && (
                <div className="inline-flex items-center gap-2 bg-green-500/10 px-4 py-1 rounded-full border border-green-500/20">
                  <div className="h-1.5 w-1.5 bg-green-500 rounded-full animate-ping"></div>
                  <span className="text-[9px] font-black text-green-400 tracking-[0.2em] uppercase">Vastavik Samay (Live)</span>
                </div>
              )}
            </div>
          </div>

          <div className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar bg-black/10">
            {chatHistory.length === 0 && (
              <div className="text-center py-16 space-y-4 opacity-40">
                <p className="text-gray-300 text-sm font-medium">
                  {currentLang === 'hindi' ? `"Namaste! Main Mahiru hoon."` : `"Hi! I am Mahiru. Let's talk!"`}
                </p>
              </div>
            )}

            {chatHistory.map((msg) => (
              <div key={msg.id} className={`flex flex-col ${msg.sender === 'user' ? 'items-end' : 'items-start'} animate-in fade-in slide-in-from-bottom-2 duration-500`}>
                <div className={`max-w-[85%] px-5 py-3 rounded-2xl shadow-xl ${
                  msg.sender === 'user' ? 'bg-gradient-to-br from-pink-600 to-pink-700 text-white rounded-tr-none' : 'bg-white/10 text-gray-100 rounded-tl-none border border-white/10'
                }`}>
                  <p className="text-sm md:text-base font-medium leading-relaxed">{msg.primaryText}</p>
                </div>
                {msg.secondaryText && (
                  <p className="text-[10px] text-pink-300/60 mt-1 font-bold italic px-2">{msg.secondaryText}</p>
                )}
              </div>
            ))}
            <div ref={chatEndRef} />
          </div>

          <div className="p-6 bg-black/40 border-t border-white/10 shrink-0 backdrop-blur-xl">
            {status === ConnectionStatus.CONNECTED ? (
              <button onClick={cleanup} className="w-full py-4 bg-white/5 text-gray-400 rounded-full font-black text-sm uppercase tracking-widest hover:bg-white/10 border border-white/10">End Live Session</button>
            ) : (
              <div className="flex items-center gap-3">
                <form onSubmit={handleSendMessage} className="flex-1 relative">
                  <input 
                    type="text" 
                    disabled={isProcessing}
                    value={inputText}
                    onChange={(e) => setInputText(e.target.value)}
                    placeholder={currentLang === 'hindi' ? "Kuch likhein..." : "Type something..."}
                    className="w-full bg-white/5 border border-white/10 rounded-[24px] py-4 px-6 text-sm text-gray-200 focus:outline-none focus:border-pink-500 transition-all disabled:opacity-50"
                  />
                  <button type="submit" disabled={!inputText.trim() || isProcessing} className="absolute right-3 top-2.5 p-2 text-pink-500 hover:bg-pink-500/20 rounded-full transition-all disabled:opacity-0">
                    <svg className="w-6 h-6 rotate-90" fill="currentColor" viewBox="0 0 24 24"><path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z"/></svg>
                  </button>
                </form>
                <button 
                  onClick={startVoiceMode} 
                  disabled={isProcessing}
                  className="p-4 bg-pink-600 text-white rounded-[24px] hover:scale-105 active:scale-95 transition-all shadow-xl border border-white/20 disabled:opacity-50"
                >
                  <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 24 24"><path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3z"/><path d="M17 11c0 2.76-2.24 5-5 5s-5-2.24-5-5H5c0 3.53 2.61 6.43 6 6.92V21h2v-3.08c3.39-.49 6-3.39 6-6.92h-2z"/></svg>
                </button>
              </div>
            )}
          </div>
        </div>
      </main>
      <style>{`.custom-scrollbar::-webkit-scrollbar { width: 4px; } .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(255, 77, 148, 0.2); border-radius: 10px; }`}</style>
    </div>
  );
};

