import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, Modality, Type } from '@google/genai';
import { ConnectionStatus, Message, Persona, UserProfile } from './types';
import { encode, decode, decodeAudioData, createBlob } from './utils/audio';

const MAHIRU_IMAGE_URL = "https://images.unsplash.com/photo-1578632292335-df3abbb0d586?q=80&w=1000&auto=format&fit=crop"; 

const PERSONA_COLORS: Record<Persona, string> = {
  'Friend': 'from-blue-500 to-indigo-600',
  'Girlfriend': 'from-pink-500 to-rose-600',
  'Parent': 'from-emerald-500 to-teal-600',
