                    <button onClick={() => updateProfile({ language: 'english' })} className={`py-3 rounded-2xl font-black text-xs border ${currentLang === 'english' ? 'bg-blue-600 text-white border-blue-400' : 'bg-white/5 text-gray-400 border-white/10'}`}>English</button>
