                    {["Kore", "Puck", "Charon", "Fenrir", "Zephyr"].map(v => <option key={v} value={v} className="bg-[#1a1a1c]">{v} Voice</option>)}
                  </select>
                </div>
                <button onClick={() => { if(confirm("Reset Mahiru's soul?")) { localStorage.clear(); window.location.reload(); } }} className="w-full py-4 bg-red-500/10 text-red-500 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] border border-red-500/20 hover:bg-red-500 transition-all hover:text-white">Total Identity Reset</button>
              </div>
            </div>
          </div>
        )}

        <div className="glass-panel rounded-[50px] shadow-2xl relative overflow-hidden flex flex-col flex-1 border border-white/5 mb-6 backdrop-blur-2xl">
          <div className="p-8 border-b border-white/5 bg-gradient-to-b from-white/5 to-transparent relative">
            <MahiruAvatar isSpeaking={isSpeaking} isProcessing={isProcessing} emotion={currentEmotion} persona={currentPersona} />
            <div className="text-center">
              <p className={`text-xs font-black tracking-[0.3em] uppercase transition-all duration-700 ${isSpeaking ? 'text-pink-400' : 'text-gray-500 opacity-60'}`}>
                {isSpeaking ? 'Mahiru is expressing...' : isProcessing ? 'Feeling your pulse...' : 'Soul Bound'}
              </p>
            </div>
          </div>

          <div className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar bg-black/10">
            {chatHistory.length === 0 && (
              <div className="text-center py-20 space-y-4 opacity-40">
