  'Caring': '💝', 'Thoughtful': '🤔', 'Excited': '✨', 'Strict': '📏',
  'Lonely': '🏚️', 'Playful': '😜', 'Sleepy': '😴', 'Loving': '💖'
};

const MahiruAvatar = ({ isSpeaking, isProcessing, emotion, persona }: { isSpeaking: boolean; isProcessing: boolean; emotion?: string; persona: Persona }) => (
  <div className="relative w-56 h-56 md:w-64 md:h-64 mx-auto mb-6 scale-110">
    {/* Breathe/Pulse Ring Animation */}
    <div className={`absolute inset-[-15px] rounded-full bg-gradient-to-tr transition-all duration-1000 blur-3xl opacity-40 
      ${PERSONA_CONFIG[persona].color} ${isSpeaking ? 'animate-ping' : 'animate-pulse'}`}>
    </div>

    <div className={`relative w-full h-full rounded-full overflow-hidden border-[4px] z-10 transition-all duration-700
      ${isProcessing ? 'border-pink-400 scale-95 shadow-[0_0_40px_rgba(255,77,148,0.6)]' : 'border-white/20'} shadow-2xl`}>
      <img 
        src={MAHIRU_IMAGE_URL} 
        alt="Mahiru" 
        className={`w-full h-full object-cover transition-all duration-[3000ms] ease-in-out ${isSpeaking ? 'scale-125 rotate-2' : 'scale-105 rotate-0'} hover:scale-110`} 
      />
      <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent"></div>

