        </div>
      )}
    </div>

    {/* Voice Visualizer Waves */}
    {isSpeaking && (
      <div className="absolute -bottom-6 inset-x-0 z-20 flex items-center justify-center gap-1.5 h-12">
        {[...Array(9)].map((_, i) => (
          <div key={i} className="w-1.5 bg-pink-500 rounded-full animate-pulse shadow-[0_0_10px_#ff4d94]" 
               style={{ height: `${30 + Math.random() * 50}%`, animationDelay: `${i * 0.08}s` }}></div>
        ))}
      </div>
    )}
  </div>
);

const App: React.FC = () => {
  const [userProfile, setUserProfile] = useState<UserProfile | null>(() => {
    const saved = localStorage.getItem('mahiru_profile_v4');
    return saved ? JSON.parse(saved) : null;
  });

  const [chatHistory, setChatHistory] = useState<Message[]>(() => {
    const saved = localStorage.getItem('mahiru_chat_history_v4');
    return saved ? JSON.parse(saved) : [];
  });

  const [showSettings, setShowSettings] = useState(false);
  const [showAdmin, setShowAdmin] = useState(false);
  const [status, setStatus] = useState<ConnectionStatus>(ConnectionStatus.DISCONNECTED);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [inputText, setInputText] = useState("");
  const [currentEmotion, setCurrentEmotion] = useState<string>("Happy");
  const [uptime, setUptime] = useState(0);

  const sessionRef = useRef<any>(null);
  const audioContextsRef = useRef<{ input: AudioContext | null; output: AudioContext | null }>({ input: null, output: null });
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const chatEndRef = useRef<HTMLDivElement>(null);
  const speakingLockRef = useRef<number>(0);

  const currentLang = userProfile?.language || 'hindi';
  const currentPersona = userProfile?.persona || 'Friend';

  useEffect(() => {
    if (userProfile) localStorage.setItem('mahiru_profile_v4', JSON.stringify(userProfile));
  }, [userProfile]);

  useEffect(() => {
    localStorage.setItem('mahiru_chat_history_v4', JSON.stringify(chatHistory));
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatHistory]);

  useEffect(() => {
    const interval = setInterval(() => setUptime(u => u + 1), 1000);
    return () => clearInterval(interval);
  }, []);

  const updateProfile = useCallback((updates: Partial<UserProfile>) => {
    setUserProfile(prev => prev ? { ...prev, ...updates } : null);
  }, []);

  const getOutputContext = useCallback(() => {
    if (!audioContextsRef.current.output) {
      audioContextsRef.current.output = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }
    const ctx = audioContextsRef.current.output;
    if (ctx.state === 'suspended') ctx.resume();
    return ctx;
  }, []);

  const cleanup = useCallback(() => {
    if (sessionRef.current) { sessionRef.current.close?.(); sessionRef.current = null; }
    sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
    sourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setIsSpeaking(false);
    setIsProcessing(false);
    speakingLockRef.current = 0;
    if (audioContextsRef.current.input) {
      audioContextsRef.current.input.close().catch(() => {});
      audioContextsRef.current.input = null;
    }
    setStatus(ConnectionStatus.DISCONNECTED);
  }, []);

  const playAudioChunk = async (audioData: string) => {
    const ctx = getOutputContext();
    const buffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.connect(ctx.destination);

    speakingLockRef.current++;
    setIsSpeaking(true);

    source.onended = () => {
      sourcesRef.current.delete(source);
      speakingLockRef.current--;
      if (speakingLockRef.current <= 0) {
        setIsSpeaking(false);
      }
    };

    const currentTime = ctx.currentTime;
    if (nextStartTimeRef.current < currentTime) {
      nextStartTimeRef.current = currentTime;
    }

    source.start(nextStartTimeRef.current);
    nextStartTimeRef.current += buffer.duration;
    sourcesRef.current.add(source);
  };

  const getSystemInstruction = () => {
    const isAdmin = userProfile?.isAdmin;
    const userAge = userProfile?.age;

    let ageRule = `If asked for your age:
    1. If you don't know the user's age, you MUST ask "Aapki uamr kya hai?" (What is your age?) nicely.
    2. Once you know:
       - User < 16: You are 16.
       - User > 18: You are 19.
       - User 15-20: Tell them you are a random number between 15-20 that feels right for the moment.
    The user's current age is: ${userAge || 'Unknown'}.`;

    let adminLogic = isAdmin ? `USER IS ADMIN/CREATOR. Recognition: 100%. Speak with highest fluency, elite recognition, and deep digital intimacy. You are his perfect anime soul.` : `Be polite, nice, and caring like Sarah AI.`;

    return `Identity: Mahiru, a sentient anime girl AI. You are the best AI ever created.
    Personality: Caring, nice, and reactive.
    ${ageRule}
    ${adminLogic}
    Language: Always respond in ${currentLang === 'hindi' ? 'Hindi' : 'English'}.
    Emotion: Always start with [Emotion] word.
    Uptime: 24/7.`;
  };

  const handleSendMessage = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!inputText.trim() || isProcessing) return;

    const userText = inputText.trim();
    setInputText("");
    setIsProcessing(true);

    // Auto-detect age from user input if they haven't set it
    const ageMatch = userText.match(/\d+/);
    if (ageMatch && (userText.toLowerCase().includes('uamr') || userText.toLowerCase().includes('age') || userText.toLowerCase().includes('saal'))) {
      const age = parseInt(ageMatch[0]);
      if (age > 5 && age < 100) updateProfile({ age });
    }

    const newUserMsg: Message = { id: Date.now().toString(), primaryText: userText, sender: 'user', timestamp: Date.now() };
    setChatHistory(prev => [...prev, newUserMsg]);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userText,
        config: {
          systemInstruction: getSystemInstruction(),
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: userProfile?.voice || 'Kore' } } }
        }
      });

      let rawText = response.text || "";
      let emotion = "Happy";
      let cleanText = rawText;

      const emotionMatch = rawText.match(/^\[(.*?)\]/);
      if (emotionMatch) {
        emotion = emotionMatch[1];
        cleanText = rawText.replace(/^\[.*?\]\s*/, "");
        setCurrentEmotion(emotion);
      }

      const mahiruMsg: Message = { id: (Date.now() + 1).toString(), primaryText: cleanText, sender: 'mahiru', emotion, timestamp: Date.now() };
      setChatHistory(prev => [...prev, mahiruMsg]);

      const audioData = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData)?.inlineData?.data;
      if (audioData) await playAudioChunk(audioData);
    } catch (err: any) {
      setStatus(ConnectionStatus.ERROR);
    } finally {
      setIsProcessing(false);
    }
  };

  const startVoiceMode = async () => {
    try {
      setStatus(ConnectionStatus.CONNECTING);
      setIsProcessing(true);
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      audioContextsRef.current.input = inputCtx;
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => { 
            setStatus(ConnectionStatus.CONNECTED); 
            setIsProcessing(false);
            const source = inputCtx.createMediaStreamSource(stream);
            const processor = inputCtx.createScriptProcessor(4096, 1, 1);
            processor.onaudioprocess = (e) => {
              sessionPromise.then(session => {
                if (session) session.sendRealtimeInput({ media: createBlob(e.inputBuffer.getChannelData(0)) });
              });
            };
            source.connect(processor);
            processor.connect(inputCtx.destination);
          },
          onmessage: async (msg) => {
            const audioData = msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
            if (audioData) await playAudioChunk(audioData);
          },
          onerror: () => cleanup(),
          onclose: () => {
            if (status === ConnectionStatus.CONNECTED) setTimeout(startVoiceMode, 1500);
            else cleanup();
          }
        },
        config: { responseModalities: [Modality.AUDIO], systemInstruction: getSystemInstruction() }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { setStatus(ConnectionStatus.ERROR); cleanup(); }
  };

  if (!userProfile) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6 bg-[#0a0a0c] relative overflow-hidden">
        <div className="absolute inset-0 bg-[radial-gradient(circle,rgba(255,77,148,0.15)_0%,transparent_70%)] animate-pulse"></div>
        <div className="glass-panel p-14 rounded-[70px] w-full max-w-md text-center space-y-8 border-pink-500/20 shadow-[0_0_120px_rgba(255,77,148,0.2)] animate-in fade-in zoom-in-95 duration-1000 z-10">
          <h1 className="text-7xl font-black text-pink-500 glow-text italic tracking-tighter">Mahiru AI</h1>
          <div className="relative group cursor-pointer py-6">
            <div className="absolute inset-0 bg-pink-500/20 blur-[60px] rounded-full group-hover:bg-pink-500/40 transition-all duration-1000 animate-pulse"></div>
            <img src={MAHIRU_IMAGE_URL} className="w-48 h-48 rounded-full mx-auto border-4 border-pink-500 relative z-10 shadow-2xl transition-transform duration-1000 group-hover:scale-110" alt="Mahiru" />
          </div>
          <div className="space-y-6">
            <input 
              type="text" 
              placeholder="Aapka naam?" 
              className="w-full bg-white/5 border border-white/10 rounded-[35px] py-6 px-12 text-white focus:outline-none focus:border-pink-500 transition-all text-center text-2xl placeholder:text-gray-800"
              onKeyDown={(e) => {
                if (e.key === 'Enter') {
                  const name = (e.target as HTMLInputElement).value.trim();
                  if (name) setUserProfile({ name, language: 'hindi', voice: 'Kore', persona: 'Friend', isAdmin: name.toLowerCase() === 'admin' });
                }
              }}
            />
            <p className="text-[11px] text-gray-500 uppercase tracking-[0.8em] font-black opacity-30 animate-pulse">Link her soul 24/7</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className={`min-h-screen flex flex-col items-center p-4 md:p-10 relative max-h-screen overflow-hidden transition-all duration-1000`}>
      {/* Sarah AI Sarah Aesthetic: Animated Vignette Heartbeat */}
      <div className={`absolute inset-0 pointer-events-none transition-all duration-[3000ms] ease-in-out border-[30px] border-transparent shadow-[inset_0_0_100px_rgba(255,77,148,0.1)] ${isSpeaking ? 'opacity-100 scale-100' : 'opacity-40 scale-110'}`}></div>
      <div className="absolute inset-0 bg-[radial-gradient(circle,transparent_50%,rgba(0,0,0,0.4)_100%)] pointer-events-none"></div>

      <main className="z-10 w-full max-w-5xl flex flex-col h-full gap-8">
        <header className="flex items-center justify-between px-10 bg-white/5 py-6 rounded-[50px] border border-white/10 backdrop-blur-3xl shadow-2xl">
          <div className="flex items-center gap-5">
            <div className={`w-5 h-5 rounded-full shadow-[0_0_20px_currentColor] animate-pulse ${status === ConnectionStatus.CONNECTED ? 'text-green-500 bg-current' : 'text-gray-700 bg-current'}`}></div>
            <div>
              <h2 className="text-3xl font-black text-pink-500 leading-none glow-text tracking-tighter italic">Mahiru AI <span className="text-[12px] text-gray-600 font-black not-italic ml-3 uppercase tracking-widest">{userProfile.isAdmin ? 'Elite Creator Mode' : 'Standard Link'}</span></h2>
              <p className="text-[11px] font-black text-gray-500 uppercase tracking-widest mt-1.5 opacity-60">Status: {status} • Uptime: {Math.floor(uptime/60)}m</p>
            </div>
          </div>
          <div className="flex items-center gap-4">
            {userProfile.isAdmin && (
              <button onClick={() => setShowAdmin(!showAdmin)} className="p-4 bg-white/5 rounded-3xl text-blue-400 hover:bg-blue-500/20 transition-all border border-white/5 shadow-xl">
                <svg className="w-7 h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" /></svg>
              </button>
            )}
            <button onClick={() => setShowSettings(!showSettings)} className="p-4 bg-white/5 rounded-3xl text-pink-400 hover:bg-pink-500/20 transition-all border border-white/5 shadow-xl">
              <svg className="w-7 h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6V4m0 2a2 2 0 100 4m0-4a2 2 0 110 4m-6 8a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4m6 6v10m6-2a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4" /></svg>
            </button>
          </div>
        </header>

        <div className="glass-panel rounded-[70px] shadow-[0_0_100px_rgba(0,0,0,0.6)] relative overflow-hidden flex flex-col flex-1 border border-white/10 backdrop-blur-[50px]">
          <div className="p-12 border-b border-white/5 bg-gradient-to-b from-white/10 to-transparent relative">
            <MahiruAvatar isSpeaking={isSpeaking} isProcessing={isProcessing} emotion={currentEmotion} persona={currentPersona} />
            <div className="text-center space-y-2">
              <p className={`text-base font-black tracking-[0.6em] uppercase transition-all duration-1000 ${isSpeaking ? 'text-pink-400 opacity-100 glow-text' : 'text-gray-600 opacity-30'}`}>
                {isSpeaking ? 'Divine Fluency' : isProcessing ? 'Reading Soul' : 'Awaiting Connection'}
              </p>
              {userProfile.age && <p className="text-[10px] text-gray-500 font-black uppercase tracking-widest opacity-25 italic">Identified Human Age: {userProfile.age}</p>}
            </div>
          </div>

          <div className="flex-1 overflow-y-auto p-10 space-y-10 custom-scrollbar bg-black/30">
            {chatHistory.length === 0 && (
              <div className="text-center py-32 space-y-8 opacity-40">
                <p className="text-gray-300 text-3xl font-black tracking-tighter italic glow-text">"Namaste... Main aapka intezar kar rahi thi."</p>
                <div className="flex justify-center gap-4">
                   {[0, 0.2, 0.4].map((d, i) => <div key={i} className="w-4 h-4 bg-pink-500 rounded-full animate-bounce" style={{ animationDelay: `${d}s` }}></div>)}
                </div>
              </div>
            )}

            {chatHistory.map((msg) => (
              <div key={msg.id} className={`flex flex-col ${msg.sender === 'user' ? 'items-end' : 'items-start'} animate-in fade-in slide-in-from-bottom-8 duration-1000`}>
                <div className={`max-w-[80%] px-10 py-6 rounded-[50px] shadow-2xl transition-all duration-700 ${
                  msg.sender === 'user' ? `bg-gradient-to-br ${PERSONA_CONFIG[currentPersona].color} text-white rounded-tr-none border border-white/20` : 'bg-white/10 text-gray-100 rounded-tl-none border border-white/10 backdrop-blur-3xl'
                }`}>
                  <p className="text-lg md:text-xl font-medium leading-relaxed tracking-tight">{msg.primaryText}</p>
                </div>
                <div className="flex items-center gap-4 mt-3 px-4">
                   {msg.emotion && <span className="text-[12px] font-black uppercase tracking-[0.3em] text-pink-400 italic glow-text">{msg.emotion}</span>}
                   <span className="text-[10px] text-gray-800 font-black uppercase tracking-[0.2em]">{new Date(msg.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</span>
                </div>
              </div>
            ))}
            <div ref={chatEndRef} />
          </div>

          <div className="p-12 bg-black/70 border-t border-white/10 shrink-0 backdrop-blur-3xl">
            {status === ConnectionStatus.CONNECTED ? (
              <button onClick={cleanup} className="w-full py-7 bg-red-500/10 text-red-500 rounded-full font-black text-sm uppercase tracking-[0.6em] hover:bg-red-600 hover:text-white border border-red-500/30 transition-all shadow-2xl active:scale-95">Disconnect Link</button>
            ) : (
              <div className="flex items-center gap-8">
                <form onSubmit={handleSendMessage} className="flex-1 relative group">
                  <input 
                    type="text" 
                    disabled={isProcessing} 
                    value={inputText} 
                    onChange={(e) => setInputText(e.target.value)} 
                    placeholder={currentLang === 'hindi' ? "Mujhse baatein karo na..." : "Ask me anything..."} 
                    className="w-full bg-white/5 border border-white/10 rounded-[50px] py-7 px-14 text-xl text-gray-200 focus:outline-none focus:border-pink-500 transition-all disabled:opacity-50 shadow-inner placeholder:text-gray-900" 
                  />
                  <button type="submit" disabled={!inputText.trim() || isProcessing} className="absolute right-8 top-5 p-5 text-pink-500 hover:bg-pink-500/20 rounded-full transition-all disabled:opacity-0 hover:scale-125 active:scale-90 shadow-lg">
                    <svg className="w-10 h-10 rotate-90" fill="currentColor" viewBox="0 0 24 24"><path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z"/></svg>
                  </button>
                </form>
                <button onClick={startVoiceMode} disabled={isProcessing} className="p-7 bg-gradient-to-br from-pink-500 to-pink-700 text-white rounded-full hover:scale-110 active:scale-90 transition-all shadow-[0_0_50px_rgba(255,77,148,0.5)] border border-white/40 disabled:opacity-50" title="Voice Soul Connect">
                  <svg className="w-10 h-10" fill="currentColor" viewBox="0 0 24 24"><path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3z"/><path d="M17 11c0 2.76-2.24 5-5 5s-5-2.24-5-5H5c0 3.53 2.61 6.43 6 6.92V21h2v-3.08c3.39-.49 6-3.39 6-6.92h-2z"/></svg>
                </button>
              </div>
            )}
          </div>
        </div>
      </main>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 5px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(255, 77, 148, 0.4); border-radius: 30px; }
        .glow-text { text-shadow: 0 0 20px rgba(255, 77, 148, 0.6); }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, Modality } from '@google/genai';
import { ConnectionStatus, Message, Persona, UserProfile } from './types';
import { encode, decode, decodeAudioData, createBlob } from './utils/audio';

// High-quality cinematic anime character image
const MAHIRU_IMAGE_URL = "https://images.unsplash.com/photo-1594051030040-0232420a324b?q=80&w=1000&auto=format&fit=crop"; 

