          {EMOTION_MAP[emotion]}
        </div>
      )}
    </div>

    {/* Sarah AI Visualizer - Fluid Waves */}
    {isSpeaking && (
      <div className="absolute -bottom-10 inset-x-0 z-20 flex items-center justify-center gap-2 h-16">
        {[...Array(12)].map((_, i) => (
          <div key={i} className="w-2 bg-gradient-to-t from-pink-600 to-pink-400 rounded-full animate-pulse shadow-[0_0_15px_#ff4d94]" 
               style={{ height: `${40 + Math.random() * 60}%`, animationDelay: `${i * 0.05}s` }}></div>
        ))}
      </div>
    )}
