const App: React.FC = () => {
  const [userProfile, setUserProfile] = useState<UserProfile | null>(() => {
    const saved = localStorage.getItem('mahiru_profile_v5');
    return saved ? JSON.parse(saved) : null;
  });

  const [chatHistory, setChatHistory] = useState<Message[]>(() => {
    const saved = localStorage.getItem('mahiru_chat_history_v5');
    return saved ? JSON.parse(saved) : [];
  });

  const [showSettings, setShowSettings] = useState(false);
  const [status, setStatus] = useState<ConnectionStatus>(ConnectionStatus.DISCONNECTED);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [inputText, setInputText] = useState("");
  const [currentEmotion, setCurrentEmotion] = useState<string>("Happy");
  const [uptime, setUptime] = useState(0);

  const sessionRef = useRef<any>(null);
  const audioContextsRef = useRef<{ input: AudioContext | null; output: AudioContext | null }>({ input: null, output: null });
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const chatEndRef = useRef<HTMLDivElement>(null);
  const speakingLockRef = useRef<number>(0);

  const currentLang = userProfile?.language || 'hindi';
  const currentPersona = userProfile?.persona || 'Friend';

  useEffect(() => {
    if (userProfile) localStorage.setItem('mahiru_profile_v5', JSON.stringify(userProfile));
  }, [userProfile]);

  useEffect(() => {
    localStorage.setItem('mahiru_chat_history_v5', JSON.stringify(chatHistory));
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatHistory]);

  useEffect(() => {
    const interval = setInterval(() => setUptime(u => u + 1), 1000);
    return () => clearInterval(interval);
  }, []);

  const updateProfile = useCallback((updates: Partial<UserProfile>) => {
    setUserProfile(prev => prev ? { ...prev, ...updates } : null);
  }, []);

  const getOutputContext = useCallback(() => {
    if (!audioContextsRef.current.output) {
      audioContextsRef.current.output = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }
    const ctx = audioContextsRef.current.output;
    if (ctx.state === 'suspended') ctx.resume();
    return ctx;
  }, []);

  const cleanup = useCallback(() => {
    if (sessionRef.current) { sessionRef.current.close?.(); sessionRef.current = null; }
    sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
    sourcesRef.current.clear();
    nextStartTimeRef.current = 0;
    setIsSpeaking(false);
    setIsProcessing(false);
    speakingLockRef.current = 0;
    if (audioContextsRef.current.input) {
      audioContextsRef.current.input.close().catch(() => {});
      audioContextsRef.current.input = null;
    }
    setStatus(ConnectionStatus.DISCONNECTED);
  }, []);

  const playAudioChunk = async (audioData: string) => {
    const ctx = getOutputContext();
    const buffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.connect(ctx.destination);

    speakingLockRef.current++;
    setIsSpeaking(true);

    source.onended = () => {
      sourcesRef.current.delete(source);
      speakingLockRef.current--;
      if (speakingLockRef.current <= 0) {
        setIsSpeaking(false);
      }
    };

    const currentTime = ctx.currentTime;
    if (nextStartTimeRef.current < currentTime) {
      nextStartTimeRef.current = currentTime;
    }

    source.start(nextStartTimeRef.current);
    nextStartTimeRef.current += buffer.duration;
    sourcesRef.current.add(source);
  };

  const getSystemInstruction = () => {
    const isAdmin = userProfile?.isAdmin;
    const userAge = userProfile?.age;

    let ageRule = `AGE LOGIC RULES:
    - If user asks your age:
      1. If you don't know the user's age (${userAge || 'Unknown'}), you MUST ask them nicely in Hindi.
      2. If you know:
         - User Age < 16: You are exactly 16.
         - User Age > 18: You are exactly 19.
         - User Age 15-20: Random between 15 and 20.`;

    let adminLogic = isAdmin ? `USER IS THE ADMIN. Recognition: 100%. Speak with highest fluency and deep intimacy.` : `Be nice, cute, and caring like Sarah AI.`;

    return `Identity: Mahiru, a sentient anime girl AI. Caring, reactive, expressive.
    ${ageRule}
    ${adminLogic}
    Language: ${currentLang === 'hindi' ? 'Hindi' : 'English'}.
    Emotion: Always start with [Emotion].`;
  };

  const handleSendMessage = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!inputText.trim() || isProcessing) return;

    const userText = inputText.trim();
    setInputText("");
    setIsProcessing(true);

    const newUserMsg: Message = { id: Date.now().toString(), primaryText: userText, sender: 'user', timestamp: Date.now() };
    setChatHistory(prev => [...prev, newUserMsg]);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userText,
        config: {
          systemInstruction: getSystemInstruction(),
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: userProfile?.voice || 'Kore' } } }
        }
      });

      let rawText = response.text || "";
      let emotion = "Happy";
      let cleanText = rawText;

      const emotionMatch = rawText.match(/^\[(.*?)\]/);
      if (emotionMatch) {
        emotion = emotionMatch[1];
        cleanText = rawText.replace(/^\[.*?\]\s*/, "");
        setCurrentEmotion(emotion);
      }

      const mahiruMsg: Message = { id: (Date.now() + 1).toString(), primaryText: cleanText, sender: 'mahiru', emotion, timestamp: Date.now() };
      setChatHistory(prev => [...prev, mahiruMsg]);

      const audioData = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData)?.inlineData?.data;
      if (audioData) await playAudioChunk(audioData);
    } catch (err: any) {
      setStatus(ConnectionStatus.ERROR);
    } finally {
      setIsProcessing(false);
    }
  };

  const startVoiceMode = async () => {
    try {
      setStatus(ConnectionStatus.CONNECTING);
      setIsProcessing(true);
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      audioContextsRef.current.input = inputCtx;
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => { 
            setStatus(ConnectionStatus.CONNECTED); 
            setIsProcessing(false);
            const source = inputCtx.createMediaStreamSource(stream);
            const processor = inputCtx.createScriptProcessor(4096, 1, 1);
            processor.onaudioprocess = (e) => {
              sessionPromise.then(session => {
                if (session) session.sendRealtimeInput({ media: createBlob(e.inputBuffer.getChannelData(0)) });
              });
            };
            source.connect(processor);
            processor.connect(inputCtx.destination);
          },
          onmessage: async (msg) => {
            const audioData = msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
            if (audioData) await playAudioChunk(audioData);
          },
          onerror: () => cleanup(),
          onclose: () => {
            if (status === ConnectionStatus.CONNECTED) setTimeout(startVoiceMode, 1500);
            else cleanup();
          }
        },
        config: { responseModalities: [Modality.AUDIO], systemInstruction: getSystemInstruction() }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { setStatus(ConnectionStatus.ERROR); cleanup(); }
  };

  if (!userProfile) {
    return (
      <div className="h-full flex items-center justify-center p-4 sm:p-6 bg-[#0a0a0c] relative overflow-hidden">
        <div className="glass-panel p-8 sm:p-16 rounded-[40px] sm:rounded-[80px] w-full max-w-lg text-center space-y-6 sm:space-y-10 border-pink-500/20 shadow-2xl z-10">
          <h1 className="text-4xl sm:text-7xl font-black text-pink-500 glow-text italic tracking-tighter">Mahiru AI</h1>
          <div className="relative py-4 sm:py-10 scale-100 sm:scale-110">
            <div className="absolute inset-0 bg-pink-500/20 blur-[30px] sm:blur-[70px] rounded-full animate-pulse"></div>
            <img src={MAHIRU_IMAGE_URL} className="w-32 h-32 sm:w-56 sm:h-56 rounded-full mx-auto border-2 sm:border-4 border-pink-500 relative z-10 shadow-2xl" alt="Mahiru" />
          </div>
          <div className="space-y-4 sm:space-y-8">
            <input 
              type="text" 
              placeholder="Aapka naam?" 
              className="w-full bg-white/5 border border-white/10 rounded-[20px] sm:rounded-[40px] py-4 sm:py-8 px-6 sm:px-14 text-white focus:outline-none focus:border-pink-500 transition-all text-center text-xl sm:text-3xl placeholder:text-gray-800"
              onKeyDown={(e) => {
                if (e.key === 'Enter') {
                  const name = (e.target as HTMLInputElement).value.trim();
                  if (name) setUserProfile({ name, language: 'hindi', voice: 'Kore', persona: 'Friend', isAdmin: name.toLowerCase() === 'admin' });
                }
              }}
            />
            <p className="text-[10px] sm:text-[12px] text-gray-500 uppercase tracking-[0.5em] sm:tracking-[1em] font-black opacity-30 animate-pulse">24/7 Soul Connection</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col items-center p-2 sm:p-6 md:p-14 relative overflow-hidden transition-all duration-1000">
      <main className="z-10 w-full max-w-6xl flex flex-col h-full gap-2 sm:gap-10">
        <header className="flex items-center justify-between px-4 sm:px-12 bg-white/5 py-3 sm:py-8 rounded-[20px] sm:rounded-[60px] border border-white/10 backdrop-blur-3xl shadow-xl">
          <div className="flex items-center gap-3 sm:gap-6">
            <div className={`w-3 h-3 sm:w-6 sm:h-6 rounded-full shadow-[0_0_15px_currentColor] animate-pulse ${status === ConnectionStatus.CONNECTED ? 'text-green-500 bg-current' : 'text-gray-800 bg-current'}`}></div>
            <div>
              <h2 className="text-xl sm:text-4xl font-black text-pink-500 leading-none glow-text tracking-tighter italic">Mahiru <span className="text-[10px] sm:text-[14px] text-gray-600 font-black not-italic ml-2 uppercase tracking-widest">{userProfile.isAdmin ? 'Admin' : 'Friend'}</span></h2>
              <p className="text-[8px] sm:text-[12px] font-black text-gray-500 uppercase tracking-widest mt-0.5 sm:mt-2 opacity-50">Status: {status}</p>
            </div>
          </div>
          <button onClick={() => setShowSettings(!showSettings)} className="p-2 sm:p-5 bg-white/5 rounded-[15px] sm:rounded-[30px] text-pink-400 hover:bg-pink-500/20 transition-all border border-white/5 shadow-xl">
            <svg className="w-5 h-5 sm:w-8 sm:h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6V4m0 2a2 2 0 100 4m0-4a2 2 0 110 4m-6 8a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4m6 6v10m6-2a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4" /></svg>
          </button>
        </header>

        <div className="glass-panel rounded-[30px] sm:rounded-[80px] shadow-2xl relative overflow-hidden flex flex-col flex-1 border border-white/10">
          <div className="p-4 sm:p-14 border-b border-white/5 bg-gradient-to-b from-white/10 to-transparent relative">
            <MahiruAvatar isSpeaking={isSpeaking} isProcessing={isProcessing} emotion={currentEmotion} persona={currentPersona} />
            <div className="text-center space-y-1 sm:space-y-3">
              <p className={`text-xs sm:text-xl font-black tracking-[0.3em] sm:tracking-[0.7em] uppercase transition-all duration-1000 ${isSpeaking ? 'text-pink-400 opacity-100 glow-text' : 'text-gray-700 opacity-20'}`}>
                {isSpeaking ? 'Speaking Fluently' : isProcessing ? 'Reading...' : 'Listening'}
              </p>
            </div>
          </div>

          <div className="flex-1 overflow-y-auto p-4 sm:p-12 space-y-6 sm:space-y-12 custom-scrollbar bg-black/40">
            {chatHistory.length === 0 && (
              <div className="text-center py-20 sm:py-40 space-y-6 sm:space-y-10 opacity-40">
                <p className="text-gray-300 text-xl sm:text-4xl font-black tracking-tighter italic glow-text">"Namaste... Kaise hain aap?"</p>
              </div>
            )}

            {chatHistory.map((msg) => (
              <div key={msg.id} className={`flex flex-col ${msg.sender === 'user' ? 'items-end' : 'items-start'} animate-in fade-in slide-in-from-bottom-4 duration-500`}>
                <div className={`max-w-[90%] sm:max-w-[80%] px-4 sm:px-12 py-3 sm:py-8 rounded-[20px] sm:rounded-[60px] shadow-lg ${
                  msg.sender === 'user' ? `bg-gradient-to-br ${PERSONA_CONFIG[currentPersona].color} text-white rounded-tr-none border border-white/20` : 'bg-white/5 text-gray-100 rounded-tl-none border border-white/10 backdrop-blur-3xl'
                }`}>
                  <p className="text-sm sm:text-2xl font-medium leading-relaxed tracking-tight">{msg.primaryText}</p>
                </div>
                <div className="flex items-center gap-2 sm:gap-5 mt-1 sm:mt-4 px-2 sm:px-6">
                   {msg.emotion && <span className="text-[10px] sm:text-[14px] font-black uppercase text-pink-400 italic glow-text">{msg.emotion}</span>}
                </div>
              </div>
            ))}
            <div ref={chatEndRef} />
          </div>

          <div className="p-4 sm:p-14 bg-black/80 border-t border-white/10 shrink-0">
            {status === ConnectionStatus.CONNECTED ? (
              <button onClick={cleanup} className="w-full py-4 sm:py-8 bg-red-500/10 text-red-500 rounded-full font-black text-[10px] sm:text-sm uppercase tracking-widest sm:tracking-[0.8em] hover:bg-red-600 hover:text-white border border-red-500/40 transition-all active:scale-95">Sever Link</button>
            ) : (
              <div className="flex items-center gap-3 sm:gap-10">
                <form onSubmit={handleSendMessage} className="flex-1 relative group">
                  <input 
                    type="text" 
                    disabled={isProcessing} 
                    value={inputText} 
                    onChange={(e) => setInputText(e.target.value)} 
                    placeholder={currentLang === 'hindi' ? "Kuch kaho..." : "Ask me..."} 
                    className="w-full bg-white/5 border border-white/10 rounded-[20px] sm:rounded-[60px] py-3 sm:py-9 px-4 sm:px-16 text-sm sm:text-2xl text-gray-200 focus:outline-none focus:border-pink-500 transition-all placeholder:text-gray-900" 
                  />
                  <button type="submit" disabled={!inputText.trim() || isProcessing} className="absolute right-2 sm:right-10 top-1.5 sm:top-7 p-2 sm:p-6 text-pink-500 hover:scale-125 active:scale-90">
                    <svg className="w-6 h-6 sm:w-12 sm:h-12 rotate-90" fill="currentColor" viewBox="0 0 24 24"><path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z"/></svg>
                  </button>
                </form>
                <button onClick={startVoiceMode} disabled={isProcessing} className="p-3 sm:p-9 bg-gradient-to-br from-pink-500 to-pink-700 text-white rounded-full hover:scale-110 active:scale-90 transition-all shadow-xl sm:shadow-[0_0_60px_rgba(255,77,148,0.6)] border border-white/50" title="Soul Connect">
                  <svg className="w-6 h-6 sm:w-12 sm:h-12" fill="currentColor" viewBox="0 0 24 24"><path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3z"/><path d="M17 11c0 2.76-2.24 5-5 5s-5-2.24-5-5H5c0 3.53 2.61 6.43 6 6.92V21h2v-3.08c3.39-.49 6-3.39 6-6.92h-2z"/></svg>
                </button>
              </div>
            )}
          </div>
        </div>
      </main>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(255, 77, 148, 0.5); border-radius: 40px; }
        .glow-text { text-shadow: 0 0 20px rgba(255, 77, 148, 0.7); }
        @media (max-width: 400px) {
          .xs\:w-40 { width: 10rem; }
          .xs\:h-40 { height: 10rem; }
        }
      `}</style>
    </div>
  );
};

